create extension if not exists pgcrypto;

create table if not exists users (id uuid primary key, email varchar(320) unique not null, display_name varchar(160), status varchar(30) not null default 'active', created_at timestamptz not null default now());
create table if not exists projects (id uuid primary key default gen_random_uuid(), name varchar(160) not null, description text, owner_id uuid not null references users(id), status varchar(30) not null default 'active', created_at timestamptz not null default now());
create table if not exists project_members (project_id uuid references projects(id) on delete cascade, user_id uuid references users(id) on delete cascade, role varchar(30) not null default 'reader', primary key(project_id,user_id));
create table if not exists datasets (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, name varchar(160) not null, version int not null default 1, storage_key text, metadata_json jsonb not null default '{}'::jsonb);
create table if not exists architectures (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, name varchar(160) not null, family varchar(30) not null, config_json jsonb not null, version int not null default 1);
create table if not exists training_jobs (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, architecture_id uuid not null references architectures(id), dataset_id uuid references datasets(id), status varchar(30) not null default 'QUEUED', progress int not null default 0, current_epoch int not null default 0, total_epochs int not null default 10, loss double precision, error_message text, started_at timestamptz, ended_at timestamptz, created_at timestamptz not null default now());
create table if not exists training_metrics (id uuid primary key default gen_random_uuid(), job_id uuid not null references training_jobs(id) on delete cascade, epoch int not null, metric_name varchar(80) not null, metric_value double precision not null, recorded_at timestamptz not null default now());
create table if not exists model_versions (id uuid primary key default gen_random_uuid(), project_id uuid not null references projects(id) on delete cascade, job_id uuid not null references training_jobs(id), version varchar(40) not null, storage_key text, status varchar(30) not null default 'draft', checksum varchar(128), created_at timestamptz not null default now());
create table if not exists audit_events (id uuid primary key default gen_random_uuid(), actor_id uuid not null references users(id), project_id uuid references projects(id) on delete set null, action varchar(100) not null, metadata_json jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create index if not exists ix_training_jobs_project_created on training_jobs(project_id, created_at desc);
create index if not exists ix_training_metrics_job_epoch on training_metrics(job_id, epoch);
